	nodeVar181 = max( vec4<f32>( ( outgoingLight + EmissiveColor ), DiffuseColor.w ), vec4<f32>( 0.0 ) );
	Output = nodeVar181;

	// result

	output.color = nodeVar181;

	return output;

}
